// === Tab: mySketch.js ===
//Credit for original project I am modifying (rain that increases/decreases in intensity depending on mouse position): Lily
// https://openprocessing.org/user/167511/#sketches

var d = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(204, 212, 224);

  for (var i = 0; i < 500; i++) {
    d.push(new Drop(random(0, windowWidth), random(0, windowHeight), random(2, 4)));
		// generate 500 raindrops at the start, these will be used throughout
  }
}

function draw() {
	// fade effect: shade background with alpha bkgd
	noStroke();
  fill(82, 89, 99);
  rect(0, 0, width, height);

	//Ground
	fill(48, 59, 55);
	ellipse(750, 550, 1500, 200);

	// i'm guessing this updates each particle on screen?
  for (var i = 0; i < d.length; i++) {
    d[i].displ();
  }

	//Drawing a window over the rain
	noStroke();
	//Frame:
	fill(177, 183, 186);
	rect(0, 580, windowWidth, 100);
	rect(0, 0, windowWidth, 40);
	rect(0, 0, 150, windowHeight);
	rect(1400, 0, 160, windowHeight);
	rect(710, 0, 110, windowHeight);

	//Apple on windowsill
	fill(71, 58, 49);
	rect(1175, 450, 15, 50);

	fill(122, 74, 65);
	ellipse(1200, 550, 120, 130);
	ellipse(1165, 550, 120, 130);

	fill(212, 197, 199);
	ellipse(1135, 510, 20, 20);
	ellipse(1125, 520, 10, 12);
}

function Drop(x, y, sp) {
  var x1 = x;
  var y1 = y;
  var x2;
  var y2;
  var s = sp;

  this.displ = function() {
    // converts mouse position. could also use map() to avoid mx <= 0
		var mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / 120;
    if (mx <= 0) {
      mx = 0.5; // default, works as a failsafe. old one was too slow for me
    }

    y1 = y1 + s * mx; // scales speed according to mouse position
    x2 = x1;
    y2 = y1 + 30; // length of raindrops, change if they're too long/short

    stroke(100, 117, 125);
    line(x1, y1, x2, y2); // draws raindrop

    if (y1 >= windowHeight - 80) { // did the drop hit the ground?
			noFill();
      noStroke();
      fill(255, 150);
      ellipse(x1, windowHeight - random(5, 50), random(2, 5), random(1, 4)); // then draw a splash

			// renews the drop by sending it back to the top (no need to generate new ones)
			x1 = random(0, windowWidth);
      y1 = -120;
    }
  }

}

